fn xmlRegNewState(mut ctxt: xmlRegParserCtxtPtr) -> xmlRegStatePtr { unsafe {
    let ret = xmlMalloc.expect("non-null function pointer")(
        ::core::mem::size_of::<xmlRegState>() as size_t
    ) as xmlRegStatePtr;
    if ret.is_null() {
        xmlRegexpErrMemory(
            ctxt,
            b"allocating state\0" as *const u8 as *const c_char,
        );
        return ::core::ptr::null_mut::<xmlRegState>();
    }
    // SAFETY: `ret` was just allocated by `xmlMalloc` with at least `size_of::<xmlRegState>()`
    // bytes and is non-null, so writing a zeroed `xmlRegState` initializes the allocation.
    ::core::ptr::write(ret, ::core::mem::zeroed());
    (*ret).type_0 = XML_REGEXP_TRANS_STATE;
    (*ret).mark = XML_REGEXP_MARK_NORMAL;
    ret
} }

